let db;try{db=JSON.parse(localStorage.getItem('naqty-demo-v1'))||{users:{},active:null}}catch{db={users:{},active:null}}
let step=0,onboard={},filter='Барлығы',chat=[],busy=false;
const user=()=>db.users[db.active];
function persist(){try{localStorage.setItem('naqty-demo-v1',JSON.stringify(db));return true}catch{toast('Сақтау мүмкін болмады. Браузер жадын тексеріңіз.');return false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3300)}
const logo=()=>'<a class="logo" href="#/"><span class="mark">N</span>NAQTY<span style="color:var(--yellow)">.</span></a>';
