const completed=()=>Object.values(user().tasks).filter(t=>t.status==='Аяқталған').length;
const lessonCount=()=>courses.reduce((a,c)=>a+c.lessons.length,0);
const nextLesson=()=>{for(let c=0;c<courses.length;c++)for(let l=0;l<courses[c].lessons.length;l++)if(!user().lessons.includes(`${c}-${l}`))return `#/lesson/${c}/${l}`;return '#/learn'};
function landing(){return `<div class="landing"><nav>${logo()}<div><a class="textbtn" href="#/login">Кіру</a><a class="btn" href="#/register">Тіркелу ↗</a></div></nav><main><section class="hero"><div><div class="tag">АЛҒАШҚЫ ҚАДАМ. НАҚТЫ НӘТИЖЕ.</div><h1>Идеяңды<br><span>нақты кәсіпке</span><br>айналдыр</h1><p>Деңгейіңе сай тапсырмалар, пайдалы сабақтар және AI көмекші арқылы бизнес бастауды үйрен.</p><a class="btn" href="#/register">Бастауды қалаймын <span>↗</span></a><p style="font-size:13px;margin-top:22px">Қазақ тілінде · Өз қарқыныңмен · Тәжірибе арқылы</p></div><div class="hero-art">${photo(0,'','Кәсіп жоспарын дайындап отырған кәсіпкер')}<div class="float-card"><span class="symbol">✓</span><div><b>Үлкен кәсіп шағын<br>қадамнан басталады</b><small>Бүгін алғашқы қадамыңды жаса</small></div></div></div></section><div class="tag">СЕНІҢ КӘСІПКЕРЛІК ЖОЛЫҢ</div><h2 style="margin-top:12px">Үйрен. Қолданып көр. Дамыт.</h2><section class="features"><article class="card">${photo(0)}<h3>Деңгейіңе сай тапсырмалар</h3><p class="muted">Идея таңдаудан бастап, дайын жоба үлгісін талдауға дейін.</p></article><article class="card">${photo(2)}<h3>Іске жарайтын білім</h3><p class="muted">Қысқа сабақтар, түсінікті мысалдар және өз қарқыныңмен оқу.</p></article><article class="card">${photo(1)}<h3>Әр қадамда көмек</h3><p class="muted">NAQTY AI демосымен идеяны талқылап, келесі қадамды жоспарла.</p></article></section></main><footer class="footer"><span>© 2026 NAQTY</span><span>Демо нұсқа · Деректер осы браузерде сақталады</span></footer></div>`}
function auth(register){return `<div class="auth-wrap"><aside class="auth-visual">${logo()}<div><div class="tag" style="color:#e7eddb">СЕНІҢ ИДЕЯҢ. СЕНІҢ КӘСІБІҢ.</div><h1>Бірінші қадамды<br>бірге жасайық.</h1>${photo(2)}<p>Кәсіпкерлік — үйренуге болатын дағды.</p></div><small style="color:white">NAQTY · Қазақ тіліндегі бизнес білімі</small></aside><main class="auth-main"><form id="auth" class="form" data-register="${register}" novalidate>${logo()}<h2 style="margin-top:32px">${register?'Қош келдіңіз!':'Қайта оралуыңызбен!'}</h2><p class="muted">${register?'Кәсіпкерлік жолыңызды бастаңыз.':'Оқуды тоқтаған жеріңізден жалғастырыңыз.'}</p><div class="notice">Демо режимі. Бұл нақты аккаунт емес. Деректер тек осы браузерде сақталады. Құпиясөз сақталмайды әрі тексерілмейді; шынайы құпиясөзіңізді қолданбаңыз.</div>${register?'<div class="field"><label for="name">Атыңыз</label><input id="name" name="name" autocomplete="given-name" maxlength="60" required></div>':''}<div class="field"><label for="email">Электрондық пошта</label><input id="email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="password">Демо құпиясөз</label><div class="password"><input id="password" name="password" type="password" autocomplete="off" placeholder="Кемінде 8 таңба" required minlength="8"><button type="button" data-action="password" aria-label="Құпиясөзді көрсету">Көрсету</button></div></div><p id="form-error" class="error" role="alert"></p><button class="full">${register?'Тіркелу':'Демо профильге кіру'} ↗</button><p style="text-align:center;margin-top:22px;font-size:14px">${register?'Профиліңіз бар ма? <a href="#/login"><b>Кіру</b></a>':'Алғаш рет келдіңіз бе? <a href="#/register"><b>Тіркелу</b></a>'}</p><a class="textbtn" href="#/">← Алғашқы бетке</a></form></main></div>`}
function onboarding(){return `<main class="onboarding card">${logo()}<div class="steps">${[0,1,2].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div class="tag">${step+1} / 3 ҚАДАМ</div><h2 style="margin-top:18px">${['Жасыңыз нешеде?','Бизнес бойынша тәжірибеңіз қандай?','Бұған дейін бизнес бастап көрдіңіз бе?'][step]}</h2><p class="muted">${['Жас рейтингке де, мүмкіндіктерге де әсер етпейді.','Сізге сәйкес тапсырмаларды ұсынамыз.','Тәжірибеңізге сүйеніп, алғашқы қадамды таңдаймыз.'][step]}</p><form id="onboarding" novalidate>${step===0?`<div class="field"><label for="age">Жасыңыз</label><input id="age" name="age" type="number" min="1" max="120" value="${onboard.age||''}" inputmode="numeric"></div>`:(step===1?levels:['Иә','Жоқ']).map((v,i)=>`<button type="button" class="choice ${(step===1?onboard.level===i:onboard.started===(i===0))?'selected':''}" data-action="choice" data-value="${i}">${v}</button>`).join('')}<p class="error" id="form-error" role="alert"></p><div class="actions">${step?'<button type="button" class="secondary" data-action="back-step">Артқа</button>':''}<button style="flex:1">${step===2?'Оқуды бастау':'Жалғастыру'} →</button></div></form></main>`}
const navs=[['home','⌂','Басты бет'],['tasks','▤','Менің тапсырмаларым'],['learn','▣','Оқу орталығы'],['ai','✧','NAQTY AI'],['profile','○','Менің профилім']];
function shell(page,body){const u=user();return `<aside class="sidebar" id="sidebar">${logo()}<small style="margin:0 15px 10px;letter-spacing:1px">ЖЕКЕ КАБИНЕТ</small>${navs.map(([id,icon,label])=>`<a class="nav ${page===id?'active':''}" href="#/${id}"><span class="nav-icon">${icon}</span>${label}</a>`).join('')}<div class="sidebar-bottom"><div class="sidebar-note"><b>Күн сайын бір қадам</b><p style="margin:6px 0 0;color:var(--muted)">Кішкентай әрекет — үлкен өзгерістің бастауы.</p></div><button class="textbtn" data-action="logout">↪ &nbsp; Шығу</button></div></aside><div class="shell"><header class="topbar"><button class="mobile-menu secondary" data-action="menu" aria-label="Мәзірді ашу" aria-expanded="false">☰</button><span class="muted" style="font-size:14px">${navs.find(n=>n[0]===page)?.[2]||'Оқу жолы'}</span><span class="pill">Демо нұсқа</span><a href="#/profile" class="who"><span class="name"><b>${esc(u.name)}</b><br><small>${levels[u.level]}</small></span><span class="avatar">${esc(u.name[0]?.toUpperCase())}</span></a></header><main class="content">${body}</main></div>`}
function taskCard(t){return `<article class="card task-card"><div class="card-top"><span class="symbol">${['◇','▥','↗'][t.level]}</span><span class="pill">${status(t)}</span></div><h3>${t.title}</h3><p>${t.desc}</p><small>${levels[t.level]} · ${t.time} минут</small><div class="card-bottom"><small>${t.level===2?'Оқу жоба үлгісі':'Қадамдық тапсырма'}</small><a class="btn secondary" style="padding:8px 13px;font-size:13px" href="#/task/${t.id}">${status(t)==='Басталмаған'?'Бастау':status(t)==='Аяқталған'?'Қарау':'Жалғастыру'} ↗</a></div></article>`}
function courseCard(c,i){const done=user().lessons.filter(x=>x.startsWith(i+'-')).length;return `<article class="card course">${photo(c.img,'course-img')}<span class="pill">${c.lessons.length} сабақ · ${c.lessons.reduce((n,l)=>n+l[1],0)} минут</span><h3>${c.title}</h3><p class="muted">${c.desc}</p>${progress(Math.round(done/c.lessons.length*100))}<div class="card-bottom"><small>${done}/${c.lessons.length} сабақ аяқталды</small><a class="textbtn" href="#/course/${i}">Курсты ашу ↗</a></div></article>`}
function home(){const u=user(),tasks=assigned(),done=tasks.filter(t=>status(t)==='Аяқталған').length;return shell('home',`<section class="intro"><div class="intro-copy"><div class="tag">NAQTY-МЕН БІРГЕ ДАМЫ</div><h2 style="margin:13px 0">Біліміңді нақты<br>әрекетке айналдыр.</h2><p class="muted">Кәсіп жоспары, клиентпен жұмыс және жаңа мүмкіндіктер. Кәсіпкерлік жолында бірге қадам басайық.</p><a class="textbtn" href="#/learn">Оқу орталығына →</a></div><div class="intro-images">${photo(0,'','Кәсіп жоспарын дайындау')}${photo(1,'','Шағын кофехана')}</div></section><div class="greeting"><div><h2>Сәлем, ${esc(u.name)}! 👋</h2><span class="muted" style="font-size:14px">Бүгін кәсіпке бір қадам жақындайық.</span></div><a class="btn" href="${nextLesson()}">Оқуды жалғастыру →</a></div><div class="stats"><div class="card"><div class="stat-title">Орындалған тапсырмалар <span>▤</span></div><div class="stat-num">${done} <small>/ ${tasks.length} тапсырма</small></div>${progress(done/tasks.length*100)}</div><div class="card"><div class="stat-title">Оқылған сабақтар <span>▣</span></div><div class="stat-num">${u.lessons.length} <small>/ ${lessonCount()} сабақ</small></div>${progress(u.lessons.length/lessonCount()*100)}</div><div class="card accent"><small>Сіздің тәжірибе деңгейіңіз</small><h3 style="font-size:25px;margin:10px 0 5px">${levels[u.level]} ↗</h3><small>${u.started?'Тәжірибеңізді жаңа қадамға айналдырыңыз.':'Алғашқы кәсіпке берік негіз қалаңыз.'}</small></div></div><div class="section-head"><h2>Сізге арналған тапсырмалар</h2><a class="textbtn" href="#/tasks">Барлығын көру →</a></div><p class="muted" style="font-size:14px">${u.started?'Бұрынғы кәсібіңіздің деректерін қолданып, жақсарту мүмкіндігін іздеңіз.':'Жаңа идеяны шағын, қауіпсіз сынақтан бастаңыз.'}</p><div class="grid">${tasks.slice(0,3).map(taskCard).join('')}</div><div class="section-head"><h2>Білімге уақыт бөл</h2><a class="textbtn" href="#/learn">Барлық курстар →</a></div><div class="grid">${[0,u.level===0?1:3,4].map(i=>courseCard(courses[i],i)).join('')}</div>`)}
function tasks(){return shell('tasks',`<div class="pagehead"><div class="tag">БІЛІМНЕН — ӘРЕКЕТКЕ</div><h1 style="margin-top:12px">Менің тапсырмаларым</h1><p class="muted">${levels[user().level]} деңгейіне арналған ${user().level===2?'дайын жоба үлгілері':'жеке оқу жолы'}.</p></div><div class="filters">${['Барлығы','Басталмаған','Орындалуда','Аяқталған'].map(f=>`<button class="${f===filter?'selected':''}" data-action="filter" data-value="${f}">${f}</button>`).join('')}</div><div class="grid">${assigned().filter(t=>filter==='Барлығы'||status(t)===filter).map(taskCard).join('')||'<div class="card empty">Бұл мәртебедегі тапсырмалар әзірге жоқ.</div>'}</div>`)}
function taskDetail(id){const t=taskData.find(t=>t.id===id);if(!t)return notFound();const entry=user().tasks[id],p=projects[id];return shell('tasks',`<div class="detail"><a class="textbtn" href="#/tasks">← Тапсырмаларға</a><div class="pagehead"><span class="pill">${levels[t.level]} · ${t.time} минут · ${status(t)}</span><h1 style="margin-top:18px">${t.title}</h1><p class="muted">${t.desc}</p></div>${p?`<div class="card"><div class="notice">Оқу мақсатындағы үлгі. Сандар нақты бизнес нәтижесі емес; салық пен қаржыландыру шығындары есепке алынбаған.</div><h3>Мақсатты аудитория</h3><p>${p[0]}</p><h3>Бизнес-модель</h3><p>${p[1]}</p><h3>Үлгі айлық қаржылық есеп</h3><p>${p[2]}</p></div>`:''}<div class="card"><h3>${p?'Дамыту міндеттері':'Орындау қадамдары'}</h3><ol>${t.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="notice">${user().started?'Бұрынғы бизнесіңізден мысал алып, дерек пен болжамды бөлек жазыңыз.':'Алдымен шағын оқу мысалын жасаңыз, кейін оны клиентпен тексеріңіз.'}</p><h3>Күтілетін нәтиже</h3><p>${t.result}</p></div><form id="task-form" data-id="${id}" class="card"><label for="answer"><h3>Сіздің жауабыңыз</h3></label><textarea id="answer" name="answer" maxlength="12000" placeholder="Әр қадам бойынша ойыңызды осында жазыңыз…">${esc(entry?.answer||'')}</textarea><p class="error" id="form-error" role="alert"></p><div class="actions">${!entry?`<button type="button" data-action="start-task" data-id="${id}">Бастау</button>`:''}<button type="submit" class="secondary">Жауапты сақтау</button><button type="submit" name="finish" value="yes">${status(t)==='Аяқталған'?'Аяқталған жауапты жаңарту':'Аяқтау ✓'}</button></div></form></div>`)}
function learn(){return shell('learn',`<div class="pagehead"><div class="tag">ӨЗ ҚАРҚЫНЫҢМЕН ҮЙРЕН</div><h1 style="margin-top:12px">Оқу орталығы</h1><p class="muted">Кәсіпке қажет білім — қысқа әрі түсінікті сабақтарда.</p></div><div class="grid">${courses.map(courseCard).join('')}</div>`)}
function course(i){const c=courses[i];if(!c)return notFound();return shell('learn',`<div class="detail"><a class="textbtn" href="#/learn">← Оқу орталығына</a><div class="pagehead"><h1>${c.title}</h1><p class="muted">${c.desc}</p></div><div class="lesson-list">${c.lessons.map((l,j)=>`<article class="card lesson-row"><div><small>САБАҚ ${j+1} · ${l[1]} минут</small><h3 style="margin:8px 0">${l[0]}</h3><small>${user().lessons.includes(`${i}-${j}`)?'✓ Аяқталған':'Оқуға дайын'}</small></div><a class="btn secondary" href="#/lesson/${i}/${j}">Оқу →</a></article>`).join('')}</div></div>`)}
function lesson(c,l){const data=courses[c]?.lessons[l];if(!data)return notFound();return shell('learn',`<article class="detail lesson"><a class="textbtn" href="#/course/${c}">← ${courses[c].title}</a><div class="pagehead"><span class="pill">${+l+1}-сабақ · ${data[1]} минут</span><h1 style="margin-top:18px">${data[0]}</h1></div><div class="card"><h3>Негізгі ой</h3><p>${data[2]}</p><h3>Іс жүзінде</h3><p>${data[3]}</p><div class="notice"><b>Өзіңіз орындап көріңіз</b><p style="margin:8px 0">${data[4]}</p></div><div class="actions"><button data-action="finish-lesson" data-id="${c}-${l}">${user().lessons.includes(`${c}-${l}`)?'✓ Сабақ аяқталған':'Сабақты аяқтау ✓'}</button><a class="btn secondary" href="${+l+1<courses[c].lessons.length?`#/lesson/${c}/${+l+1}`:'#/learn'}">${+l+1<courses[c].lessons.length?'Келесі сабақ →':'Курстарға оралу'}</a></div></div></article>`)}
const prompts=['Бизнес идеямды талда','Неден бастауым керек?','Осы тапсырманы түсіндір','Маған бір апталық жоспар құр'];
function ai(){return shell('ai',`<div class="chat-layout"><div class="chat-welcome"><div class="symbol">✧</div><span class="tag">ОЙЫҢДЫ БІРГЕ НАҚТЫЛАЙЫҚ</span><h2 style="margin:15px 0 10px">Сәлем! Мен — NAQTY AI</h2><p class="muted">Идея, тапсырма немесе келесі қадам.<br>Бизнес туралы сұрағыңызды жазыңыз.</p></div><div class="notice">Демо ассистент: жауаптар дайын оқу үлгілерінен құралады. Нақты AI қосылмаған, хабарламалар сыртқы сервиске жіберілмейді.</div><div class="prompts">${prompts.map((p,i)=>`<button data-action="prompt" data-value="${i}">✧ &nbsp; ${p}</button>`).join('')}</div><div class="messages" aria-live="polite">${chat.map(m=>`<div class="bubble ${m.role}">${esc(m.text)}</div>`).join('')}${busy?'<div class="bubble">Жауап дайындалып жатыр…</div>':''}</div><div id="chat-error" class="error" role="alert"></div><form id="chat-form" class="chat-form"><input id="message" name="message" aria-label="Хабарлама" placeholder="Сұрағыңызды жазыңыз…" maxlength="2000" required><button ${busy?'disabled':''}>Жіберу ↑</button></form><button class="textbtn" data-action="ai-error" style="font-size:12px">Демо қате күйін көру</button></div>`)}
function profile(){const u=user();return shell('profile',`<div class="pagehead"><h1>Менің профилім</h1><p class="muted">Оқу жолыңыз бен жеке мәліметтеріңіз бір жерде.</p></div><div class="profile-grid"><form id="profile" class="card" novalidate><h3>Жеке мәліметтер</h3><div class="field"><label for="name">Атыңыз</label><input name="name" id="name" value="${esc(u.name)}" maxlength="60"></div><div class="field"><label>Электрондық пошта</label><p>${esc(u.email)}</p></div><div class="field"><label for="age">Жасыңыз</label><input name="age" id="age" type="number" min="1" max="120" value="${u.age}"></div><div class="field"><label for="level">Тәжірибе деңгейі</label><select name="level" id="level">${levels.map((v,i)=>`<option value="${i}" ${u.level===i?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="started">Бұрын бизнес бастадыңыз ба?</label><select name="started" id="started"><option value="yes" ${u.started?'selected':''}>Иә</option><option value="no" ${!u.started?'selected':''}>Жоқ</option></select></div><small>Жас мүмкіндіктерді шектемейді. Деңгейді өзгертсеңіз, жаңа тапсырмалар ұсынылады; бұрынғы прогресс сақталады.</small><p id="form-error" class="error" role="alert"></p><button>Өзгерістерді сақтау</button></form><div><div class="card"><h3>Менің жетістігім</h3><p><b>${completed()}</b> аяқталған тапсырма</p><p><b>${u.lessons.length} / ${lessonCount()}</b> оқылған сабақ</p>${progress(Math.round(u.lessons.length/lessonCount()*100))}<h3 style="margin-top:25px">Аяқталған тапсырмалар</h3>${taskData.filter(t=>status(t)==='Аяқталған').map(t=>`<p><a href="#/task/${t.id}">✓ ${t.title} →</a></p>`).join('')||'<p class="muted">Алғашқы тапсырманы аяқтап, жетістігіңізді осында көріңіз.</p>'}</div><div class="notice">Бұл құрылғыдағы демо профиль. Браузер деректерін тазаласаңыз, сақталған прогресс жойылады.</div></div></div>`)}
function notFound(){return '<main class="onboarding card"><h2>Бет табылмады</h2><a class="btn" href="#/home">Басты бетке</a></main>'}
function render(){const route=(location.hash.slice(1)||'/').split('/').filter(Boolean),p=route[0]||'';let html;if(!p)html=landing();else if(['login','register'].includes(p))html=auth(p==='register');else if(!user()){location.hash='/login';return}else if(!user().onboarded)html=onboarding();else{html=({home, tasks,learn,ai,profile}[p]?.()??(p==='task'?taskDetail(route[1]):p==='course'?course(+route[1]):p==='lesson'?lesson(+route[1],+route[2]):home()))}$('#app').innerHTML=html;document.title=`${navs.find(n=>n[0]===p)?.[2]||'Идеядан кәсіпке'} · NAQTY`}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='password'){const el=$('#password');el.type=el.type==='password'?'text':'password';b.textContent=el.type==='password'?'Көрсету':'Жасыру';b.setAttribute('aria-label',b.textContent)}else if(a==='menu'){const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',open)}else if(a==='logout'){db.active=null;persist();chat=[];location.hash='/'}else if(a==='choice'){if(step===1)onboard.level=+b.dataset.value;else onboard.started=+b.dataset.value===0;render()}else if(a==='back-step'){step--;render()}else if(a==='filter'){filter=b.dataset.value;render()}else if(a==='start-task'){user().tasks[b.dataset.id]={status:'Орындалуда',answer:$('#answer').value};if(persist()){render();toast('Тапсырма басталды')}}else if(a==='finish-lesson'){if(!user().lessons.includes(b.dataset.id))user().lessons.push(b.dataset.id);if(persist()){render();toast('Сабақ аяқталды. Жарайсыз!')}}else if(a==='prompt'){sendChat(prompts[+b.dataset.value])}else if(a==='ai-error'){$('#chat-error').innerHTML='Демо қате: жауап алу мүмкін болмады. <button class="textbtn" data-action="retry">Қайта көру</button>'}else if(a==='retry'){$('#chat-error').textContent='';sendChat(chat.filter(m=>m.role==='user').at(-1)?.text||prompts[1])}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form),err=msg=>{$('#form-error').textContent=msg};if(form.id==='auth'){const name=String(fd.get('name')||'').trim(),email=String(fd.get('email')).trim().toLowerCase(),pass=String(fd.get('password')),reg=form.dataset.register==='true';if(reg&&name.length<2)return err('Атыңызды кемінде 2 таңбамен жазыңыз.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return err('Электрондық поштаны дұрыс енгізіңіз.');if(pass.length<8)return err('Демо құпиясөз кемінде 8 таңбадан тұрсын.');if(reg&&db.users[email])return err('Бұл поштада демо профиль бар. Кіру бетін қолданыңыз.');if(!reg&&!db.users[email])return err('Осы браузерде профиль табылмады. Алдымен тіркеліңіз.');if(reg)db.users[email]={name,email,tasks:{},lessons:[],onboarded:false};db.active=email;form.reset();step=0;onboard={};if(persist())location.hash='/home'}else if(form.id==='onboarding'){if(step===0){const age=Number(fd.get('age'));if(!Number.isInteger(age)||age<1||age>120)return err('Жасыңызды 1 мен 120 аралығындағы бүтін санмен енгізіңіз.');onboard.age=age}else if(step===1&&onboard.level===undefined)return err('Тәжірибе деңгейін таңдаңыз.');else if(step===2&&onboard.started===undefined)return err('Жауаптың бірін таңдаңыз.');if(step<2){step++;render()}else{Object.assign(user(),onboard,{onboarded:true});if(persist()){location.hash='/home';render()}}}else if(form.id==='task-form'){const answer=String(fd.get('answer')).trim(),finish=e.submitter?.name==='finish';if(!answer)return err('Сақтау үшін жауабыңызды жазыңыз.');if(finish&&answer.length<20)return err('Нәтижеңізді кемінде 20 таңбамен сипаттаңыз.');const old=user().tasks[form.dataset.id];user().tasks[form.dataset.id]={answer,status:finish||old?.status==='Аяқталған'?'Аяқталған':'Орындалуда'};if(persist()){render();toast(finish?'Тапсырма аяқталды!':'Жауап сақталды')}}else if(form.id==='profile'){const name=String(fd.get('name')).trim(),age=Number(fd.get('age'));if(name.length<2)return err('Атыңызды кемінде 2 таңбамен жазыңыз.');if(!Number.isInteger(age)||age<1||age>120)return err('Жасты 1–120 аралығында енгізіңіз.');Object.assign(user(),{name,age,level:+fd.get('level'),started:fd.get('started')==='yes'});if(persist()){render();toast('Профиль жаңартылды')}}else if(form.id==='chat-form'){sendChat(String(fd.get('message')).trim())}});
async function sendChat(message){if(busy||!message)return;busy=true;chat.push({role:'user',text:message});render();try{await new Promise(r=>setTimeout(r,850));let text;if(/апта|жоспар/i.test(message))text='Бір апталық үлгі жоспар:\n\n1-күн: бір клиент мәселесін таңдаңыз.\n2-күн: үш клиентпен сөйлесіңіз.\n3-күн: үш бәсекелесті салыстырыңыз.\n4-күн: ұсынысыңызды бір сөйлеммен жазыңыз.\n5-күн: бастапқы шығындарды есептеңіз.\n6-күн: шағын ұсынысты тексеріңіз.\n7-күн: жауаптарды талдап, келесі қадамды таңдаңыз.\n\n'+(user().started?'Әр қадамды бұрынғы бизнесіңіздің дерегімен салыстырыңыз.':'Әзірге үлкен шығын жасамай, болжамды тексеруге назар аударыңыз.');else if(/тапсырма|түсіндір/i.test(message)){const t=assigned().find(t=>status(t)==='Орындалуда')||assigned()[0];text=`«${t.title}» тапсырмасынан бастайық.\n\n${t.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\nНәтиже: ${t.result}\n\nЖауапты тапсырма бетінде сақтай аласыз.`}else if(/идея|талда/i.test(message))text='Идеяны талдауға арналған демо құрылым:\n\n• Клиентіңіз кім?\n• Оның қандай нақты мәселесін шешесіз?\n• Қазір ол қандай баламаны қолданады?\n• Ұсынысыңыздың айырмашылығы неде?\n• Бір сатудан кейін қанша қаражат қалады?\n\nКелесі қадам: үш ықтимал клиентпен сөйлесіп, мәселенің бар-жоғын тексеріңіз. Бұл дайын үлгі; нақты идеяға жеке AI талдауы жасалмайды.';else text=`Сіздің деңгейіңіз: ${levels[user().level]}.\n\n«${assigned()[0].title}» тапсырмасынан бастаңыз. Күтілетін нәтиже: ${assigned()[0].result}\n\nСабақ бойынша сұрағыңыз болса, Оқу орталығындағы негізгі ой, мысал және жаттығуды бірге оқыңыз. Демо режимі еркін сұрақтарға нақты AI жауабын бере алмайды; бұл — келесі қадамға арналған оқу үлгісі.`;chat.push({role:'assistant',text:'Демо жауап\n\n'+text})}catch{chat.push({role:'assistant',text:'Жауап дайындау мүмкін болмады. Сұрақты қайта жіберіңіз.'})}finally{busy=false;if(location.hash==='#/ai'){render();$('#message')?.focus()}}}
render();
